public int rob(int[] nums) {              // House Robber I
    int prev = 0, cur = 0;                 // prev = best up to i-2, cur = up to i-1
    for (int x : nums) {
        int t = Math.max(cur, prev + x);
        prev = cur; cur = t;
    }
    return cur;
}
public int robII(int[] nums) {
    if (nums.length == 1) return nums[0];
    return Math.max(robRange(nums, 0, nums.length - 2),
                    robRange(nums, 1, nums.length - 1));
}
private int robRange(int[] nums, int lo, int hi) {
    int prev = 0, cur = 0;
    for (int i = lo; i <= hi; i++) {
        int t = Math.max(cur, prev + nums[i]);
        prev = cur; cur = t;
    }
    return cur;
}

public int numDecodings(String s) {
    int n = s.length();
    int prev2 = 1;                        // dp[0]
    int prev1 = s.charAt(0) == '0' ? 0 : 1; // dp[1]
    for (int i = 2; i <= n; i++) {
        int cur = 0;
        if (s.charAt(i - 1) != '0') cur += prev1;
        int two = (s.charAt(i - 2) - '0') * 10 + (s.charAt(i - 1) - '0');
        if (two >= 10 && two <= 26) cur += prev2;
        prev2 = prev1; prev1 = cur;
    }
    return prev1;
}

public boolean wordBreak(String s, java.util.List<String> wordDict) {
    java.util.Set<String> dict = new java.util.HashSet<>(wordDict);
    int n = s.length(), maxLen = 0;
    for (String w : dict) maxLen = Math.max(maxLen, w.length());
    boolean[] dp = new boolean[n + 1];
    dp[0] = true;
    for (int i = 1; i <= n; i++)
        for (int j = Math.max(0, i - maxLen); j < i; j++)
            if (dp[j] && dict.contains(s.substring(j, i))) { dp[i] = true; break; }
    return dp[n];
}

public int jump(int[] nums) {
    int jumps = 0, curEnd = 0, farthest = 0;
    for (int i = 0; i < nums.length - 1; i++) {
        farthest = Math.max(farthest, i + nums[i]);
        if (i == curEnd) { jumps++; curEnd = farthest; }
    }
    return jumps;
}

public int maxProduct(int[] nums) {
    int maxEnd = nums[0], minEnd = nums[0], best = nums[0];
    for (int i = 1; i < nums.length; i++) {
        int x = nums[i];
        if (x < 0) { int t = maxEnd; maxEnd = minEnd; minEnd = t; }
        maxEnd = Math.max(x, x * maxEnd);
        minEnd = Math.min(x, x * minEnd);
        best = Math.max(best, maxEnd);
    }
    return best;
}

public int lengthOfLIS_dp(int[] nums) {
