public int lengthOfLIS(int[] nums) {
    int[] tails = new int[nums.length];
    int size = 0;
    for (int x : nums) {
        int lo = 0, hi = size;
        while (lo < hi) {              // first index with tails[idx] >= x
            int mid = (lo + hi) >>> 1;
            if (tails[mid] < x) lo = mid + 1; else hi = mid;
        }
        tails[lo] = x;
        if (lo == size) size++;
    }
    return size;
}

public boolean canPartition(int[] nums) {
    int total = 0;
    for (int x : nums) total += x;
    if ((total & 1) == 1) return false;
    int target = total / 2;
    boolean[] dp = new boolean[target + 1];
    dp[0] = true;
    for (int x : nums)
        for (int s = target; s >= x; s--)
            dp[s] |= dp[s - x];
    return dp[target];
}

public int findTargetSumWays(int[] nums, int target) {
    int total = 0;
    for (int x : nums) total += x;
    if (Math.abs(target) > total || ((total + target) & 1) == 1) return 0;
    int P = (total + target) / 2;
    int[] dp = new int[P + 1];
    dp[0] = 1;
    for (int x : nums)
        for (int s = P; s >= x; s--)
            dp[s] += dp[s - x];
    return dp[P];
}

public int coinChange(int[] coins, int amount) {      // I: min coins
    int[] dp = new int[amount + 1];
    java.util.Arrays.fill(dp, amount + 1);
    dp[0] = 0;
    for (int c : coins)
        for (int a = c; a <= amount; a++)
            dp[a] = Math.min(dp[a], dp[a - c] + 1);
    return dp[amount] > amount ? -1 : dp[amount];
}
public int change(int amount, int[] coins) {          // II: count ways
    int[] dp = new int[amount + 1];
    dp[0] = 1;
    for (int c : coins)                                // coins outside => combinations
        for (int a = c; a <= amount; a++)
            dp[a] += dp[a - c];
    return dp[amount];
}

public int lastStoneWeightII(int[] stones) {
    int total = 0;
    for (int s : stones) total += s;
    int half = total / 2;
    boolean[] dp = new boolean[half + 1];
    dp[0] = true;
    int best = 0;
    for (int s : stones)
        for (int w = half; w >= s; w--)
            if (dp[w - s]) { dp[w] = true; best = Math.max(best, w); }
    return total - 2 * best;
}

public int findMaxForm(String[] strs, int m, int n) {
    int[][] dp = new int[m + 1][n + 1];
    for (String s : strs) {
        int z = 0, o = 0;
        for (char c : s.toCharArray()) { if (c == '0') z++; else o++; }
        for (int i = m; i >= z; i--)
            for (int j = n; j >= o; j--)
                dp[i][j] = Math.max(dp[i][j], dp[i - z][j - o] + 1);
    }
    return dp[m][n];
}

public int profitableSchemes(int n, int minProfit, int[] group, int[] profit) {
    int MOD = 1_000_000_007;
    long[][] dp = new long[n + 1][minProfit + 1];
    for (int g = 0; g <= n; g++) dp[g][0] = 1;      // 0 required profit: empty scheme counts
    for (int k = 0; k < group.length; k++) {
        int g = group[k], p = profit[k];
        for (int i = n; i >= g; i--)
            for (int j = minProfit; j >= 0; j--) {
                int pp = Math.min(minProfit, j + p);
                dp[i][pp] = (dp[i][pp] + dp[i - g][j]) % MOD;
            }
    }
    return (int) dp[n][minProfit];
}

public int numRollsToTarget(int n, int k, int target) {
    int MOD = 1_000_000_007;
    int[] dp = new int[target + 1];
    dp[0] = 1;
    for (int d = 1; d <= n; d++) {
        int[] next = new int[target + 1];
        for (int t = 1; t <= target; t++)
            for (int f = 1; f <= k && f <= t; f++)
                next[t] = (next[t] + dp[t - f]) % MOD;
        dp = next;
    }
    return dp[target];
}

public String largestNumber(int[] cost, int target) {
    int[] dp = new int[target + 1];
    java.util.Arrays.fill(dp, Integer.MIN_VALUE);
    dp[0] = 0;
    for (int t = 1; t <= target; t++)
        for (int d = 0; d < 9; d++)
            if (t >= cost[d] && dp[t - cost[d]] != Integer.MIN_VALUE)
                dp[t] = Math.max(dp[t], dp[t - cost[d]] + 1);
    if (dp[target] < 0) return "0";

    StringBuilder sb = new StringBuilder();
    int t = target;
    for (int d = 8; d >= 0; d--)                 // try larger digits first
        while (t >= cost[d] && dp[t] == dp[t - cost[d]] + 1) {
            sb.append((char) ('1' + d));
            t -= cost[d];
        }
    return sb.toString();
}

public int uniquePathsWithObstacles(int[][] grid) {
    int n = grid[0].length;
    int[] dp = new int[n];
    dp[0] = grid[0][0] == 0 ? 1 : 0;
    for (int[] row : grid)
        for (int j = 0; j < n; j++) {
            if (row[j] == 1) dp[j] = 0;
            else if (j > 0) dp[j] += dp[j - 1];
        }
    return dp[n - 1];
}

public int minPathSum(int[][] grid) {
    int n = grid[0].length;
    int[] dp = new int[n];
    dp[0] = grid[0][0];
    for (int j = 1; j < n; j++) dp[j] = dp[j - 1] + grid[0][j];
    for (int i = 1; i < grid.length; i++) {
        dp[0] += grid[i][0];
        for (int j = 1; j < n; j++)
            dp[j] = grid[i][j] + Math.min(dp[j], dp[j - 1]);
    }
    return dp[n - 1];
}

public int calculateMinimumHP(int[][] d) {
    int m = d.length, n = d[0].length;
    int[][] dp = new int[m + 1][n + 1];
    for (int[] row : dp) Arrays.fill(row, Integer.MAX_VALUE);
    dp[m][n - 1] = dp[m - 1][n] = 1;                 // just past the exit
    for (int i = m - 1; i >= 0; i--)
        for (int j = n - 1; j >= 0; j--) {
            int need = Math.min(dp[i + 1][j], dp[i][j + 1]) - d[i][j];
            dp[i][j] = Math.max(1, need);
        }
    return dp[0][0];
}

public int cherryPickup(int[][] grid) {
    int n = grid.length;
    Integer[][][] memo = new Integer[n][n][n];
    return Math.max(0, dp(grid, 0, 0, 0, memo, n));
}
private int dp(int[][] grid, int r1, int c1, int r2, Integer[][][] memo, int n) {
    int c2 = r1 + c1 - r2;
    if (r1 >= n || c1 >= n || r2 >= n || c2 >= n
            || grid[r1][c1] == -1 || grid[r2][c2] == -1)
        return Integer.MIN_VALUE;
    if (r1 == n - 1 && c1 == n - 1) return grid[r1][c1];
    if (memo[r1][c1][r2] != null) return memo[r1][c1][r2];
    int cherries = grid[r1][c1];
    if (r1 != r2 || c1 != c2) cherries += grid[r2][c2];
    int best = Math.max(
        Math.max(dp(grid, r1 + 1, c1, r2 + 1, memo, n), dp(grid, r1 + 1, c1, r2, memo, n)),
        Math.max(dp(grid, r1, c1 + 1, r2 + 1, memo, n), dp(grid, r1, c1 + 1, r2, memo, n)));
    if (best == Integer.MIN_VALUE) return memo[r1][c1][r2] = Integer.MIN_VALUE;
    return memo[r1][c1][r2] = cherries + best;
}

public int cherryPickup(int[][] grid) {
    int cols = grid[0].length;
    Integer[][][] memo = new Integer[grid.length][cols][cols];
    return dp(grid, 0, 0, cols - 1, memo);
}
private int dp(int[][] grid, int r, int c1, int c2, Integer[][][] memo) {
    int cols = grid[0].length;
    if (c1 < 0 || c1 >= cols || c2 < 0 || c2 >= cols) return Integer.MIN_VALUE;
    if (memo[r][c1][c2] != null) return memo[r][c1][c2];
    int cherries = grid[r][c1];
    if (c1 != c2) cherries += grid[r][c2];
    if (r < grid.length - 1) {
        int best = Integer.MIN_VALUE;
        for (int nc1 = c1 - 1; nc1 <= c1 + 1; nc1++)
            for (int nc2 = c2 - 1; nc2 <= c2 + 1; nc2++)
                best = Math.max(best, dp(grid, r + 1, nc1, nc2, memo));
        cherries += best;
    }
    return memo[r][c1][c2] = cherries;
}

public int maximalSquare(char[][] matrix) {
    int m = matrix.length, n = matrix[0].length, best = 0;
    int[] dp = new int[n + 1];
    for (int i = 1; i <= m; i++) {
        int prev = 0;                       // dp[i-1][j-1]
        for (int j = 1; j <= n; j++) {
            int tmp = dp[j];
            if (matrix[i - 1][j - 1] == '1') {
                dp[j] = Math.min(Math.min(dp[j], dp[j - 1]), prev) + 1;
                best = Math.max(best, dp[j]);
            } else dp[j] = 0;
            prev = tmp;
        }
    }
    return best * best;
}

public int[] pathsWithMaxScore(List<String> board) {
    int MOD = 1_000_000_007;
    int n = board.size();
    int[][] maxSum = new int[n + 1][n + 1];
    int[][] cnt = new int[n + 1][n + 1];
    for (int[] row : maxSum) Arrays.fill(row, -1);
    maxSum[1][1] = 0; cnt[1][1] = 1;              // 'E' at (0,0)
    int[][] dirs = {{-1, 0}, {0, -1}, {-1, -1}};
    for (int i = 1; i <= n; i++)
        for (int j = 1; j <= n; j++) {
            char ch = board.get(i - 1).charAt(j - 1);
            if (ch == 'X' || ch == 'E') continue;
            int best = -1, ways = 0;
            for (int[] d : dirs) {
                int pi = i + d[0], pj = j + d[1];
                if (maxSum[pi][pj] < 0) continue;
                if (maxSum[pi][pj] > best) { best = maxSum[pi][pj]; ways = cnt[pi][pj]; }
                else if (maxSum[pi][pj] == best) ways = (ways + cnt[pi][pj]) % MOD;
            }
            if (best < 0) continue;
            int val = ch == 'S' ? 0 : ch - '0';
            maxSum[i][j] = best + val;
            cnt[i][j] = ways;
        }
    if (maxSum[n][n] < 0) return new int[]{0, 0};
    return new int[]{maxSum[n][n], cnt[n][n]};
}

public int minDistance(String a, String b) {
    int m = a.length(), n = b.length();
    int[] dp = new int[n + 1];
    for (int j = 0; j <= n; j++) dp[j] = j;
    for (int i = 1; i <= m; i++) {
        int prev = dp[0];                 // dp[i-1][j-1]
        dp[0] = i;
        for (int j = 1; j <= n; j++) {
            int tmp = dp[j];
            if (a.charAt(i - 1) == b.charAt(j - 1)) dp[j] = prev;
            else dp[j] = 1 + Math.min(prev, Math.min(dp[j], dp[j - 1]));
            prev = tmp;
        }
    }
    return dp[n];
}

