}

public String shortestCommonSupersequence(String str1, String str2) {
    int m = str1.length(), n = str2.length();
    int[][] dp = new int[m + 1][n + 1];
    for (int i = 1; i <= m; i++)
        for (int j = 1; j <= n; j++)
            dp[i][j] = str1.charAt(i - 1) == str2.charAt(j - 1)
                ? dp[i - 1][j - 1] + 1
                : Math.max(dp[i - 1][j], dp[i][j - 1]);
    StringBuilder sb = new StringBuilder();
    int i = m, j = n;
    while (i > 0 && j > 0) {
        if (str1.charAt(i - 1) == str2.charAt(j - 1)) {
            sb.append(str1.charAt(i - 1)); i--; j--;
        } else if (dp[i - 1][j] >= dp[i][j - 1]) {
            sb.append(str1.charAt(i - 1)); i--;
        } else {
            sb.append(str2.charAt(j - 1)); j--;
        }
    }
    while (i > 0) sb.append(str1.charAt(--i));
    while (j > 0) sb.append(str2.charAt(--j));
    return sb.reverse().toString();
}

public int longestPalindromeSubseq(String s) {
    int n = s.length();
    int[][] dp = new int[n][n];
    for (int i = n - 1; i >= 0; i--) {
        dp[i][i] = 1;
        for (int j = i + 1; j < n; j++) {
            if (s.charAt(i) == s.charAt(j)) dp[i][j] = dp[i + 1][j - 1] + 2;
            else dp[i][j] = Math.max(dp[i + 1][j], dp[i][j - 1]);
        }
    }
    return dp[0][n - 1];
}

public boolean isScramble(String s1, String s2) {
    if (s1.length() != s2.length()) return false;
    return solve(s1, s2, new HashMap<>());
}
private boolean solve(String s1, String s2, Map<String, Boolean> memo) {
    if (s1.equals(s2)) return true;
    String key = s1 + "#" + s2;
    if (memo.containsKey(key)) return memo.get(key);
    int[] cnt = new int[26];
    for (int i = 0; i < s1.length(); i++) {
        cnt[s1.charAt(i) - 'a']++;
        cnt[s2.charAt(i) - 'a']--;
    }
    for (int c : cnt) if (c != 0) { memo.put(key, false); return false; }
    int n = s1.length();
    boolean res = false;
    for (int i = 1; i < n && !res; i++) {
        if (solve(s1.substring(0, i), s2.substring(0, i), memo)
                && solve(s1.substring(i), s2.substring(i), memo)) res = true;
        else if (solve(s1.substring(0, i), s2.substring(n - i), memo)
                && solve(s1.substring(i), s2.substring(0, n - i), memo)) res = true;
    }
    memo.put(key, res);
    return res;
}

public int countSubstrings(String s) {
    int n = s.length(), count = 0;
    for (int center = 0; center < 2 * n - 1; center++) {
        int l = center / 2, r = l + center % 2;
        while (l >= 0 && r < n && s.charAt(l) == s.charAt(r)) {
            count++;
            l--;
            r++;
        }
    }
    return count;
}

public String longestPalindrome(String s) {
    if (s == null || s.length() < 1) return "";
    int start = 0, end = 0;
    for (int i = 0; i < s.length(); i++) {
        int len1 = expand(s, i, i);
        int len2 = expand(s, i, i + 1);
        int len = Math.max(len1, len2);
        if (len > end - start + 1) {
            start = i - (len - 1) / 2;
            end = i + len / 2;
        }
    }
    return s.substring(start, end + 1);
}

private int expand(String s, int l, int r) {
    while (l >= 0 && r < s.length() && s.charAt(l) == s.charAt(r)) {
        l--;
        r++;
    }
    return r - l - 1;
}

public int minCut(String s) {
    int n = s.length();
    boolean[][] pal = new boolean[n][n];
    for (int i = n - 1; i >= 0; i--)
        for (int j = i; j < n; j++)
            pal[i][j] = s.charAt(i) == s.charAt(j) && (j - i < 2 || pal[i + 1][j - 1]);

    int[] cut = new int[n];
    for (int j = 0; j < n; j++) {
        if (pal[0][j]) { cut[j] = 0; continue; }
        int best = Integer.MAX_VALUE;
        for (int i = 1; i <= j; i++)
            if (pal[i][j]) best = Math.min(best, cut[i - 1] + 1);
        cut[j] = best;
    }
    return cut[n - 1];
}

public int minimumMoves(int[] arr) {
    int n = arr.length;
    int[][] dp = new int[n][n];
    for (int i = 0; i < n; i++) dp[i][i] = 1;
    for (int len = 2; len <= n; len++) {
        for (int i = 0; i + len - 1 < n; i++) {
            int j = i + len - 1;
            dp[i][j] = dp[i + 1][j] + 1;
            if (arr[i] == arr[i + 1])
                dp[i][j] = Math.min(dp[i][j], (i + 2 <= j ? dp[i + 2][j] : 0) + 1);
            for (int k = i + 2; k <= j; k++)
                if (arr[i] == arr[k])
                    dp[i][j] = Math.min(dp[i][j],
                            dp[i + 1][k - 1] + (k + 1 <= j ? dp[k + 1][j] : 0));
        }
    }
    return dp[0][n - 1];
}

public int countPalindromicSubsequences(String s) {
    int MOD = 1_000_000_007;
    int n = s.length();
    char[] c = s.toCharArray();
    long[][] dp = new long[n][n];
    for (int i = 0; i < n; i++) dp[i][i] = 1;
    for (int len = 2; len <= n; len++) {
        for (int i = 0; i + len - 1 < n; i++) {
            int j = i + len - 1;
            if (c[i] != c[j]) {
                dp[i][j] = dp[i + 1][j] + dp[i][j - 1] - dp[i + 1][j - 1];
            } else {
                int lo = i + 1, hi = j - 1;
                while (lo <= hi && c[lo] != c[i]) lo++;
                while (lo <= hi && c[hi] != c[i]) hi--;
                if (lo > hi) dp[i][j] = dp[i + 1][j - 1] * 2 + 2;
                else if (lo == hi) dp[i][j] = dp[i + 1][j - 1] * 2 + 1;
                else dp[i][j] = dp[i + 1][j - 1] * 2 - dp[lo + 1][hi - 1];
            }
            dp[i][j] = ((dp[i][j] % MOD) + MOD) % MOD;
        }
    }
    return (int) dp[0][n - 1];
}

public int maxCoins(int[] nums) {
    int n = nums.length;
    int[] arr = new int[n + 2];
    arr[0] = arr[n + 1] = 1;
    for (int i = 0; i < n; i++) arr[i + 1] = nums[i];

    int[][] dp = new int[n + 2][n + 2];
    for (int len = 2; len <= n + 1; len++)
        for (int i = 0; i + len <= n + 1; i++) {
            int k = i + len;
            for (int j = i + 1; j < k; j++)
                dp[i][k] = Math.max(dp[i][k],
                        dp[i][j] + arr[i] * arr[j] * arr[k] + dp[j][k]);
        }
    return dp[0][n + 1];
}

public int mergeStones(int[] stones, int k) {
    int n = stones.length;
    if ((n - 1) % (k - 1) != 0) return -1;
    int[] prefix = new int[n + 1];
    for (int i = 0; i < n; i++) prefix[i + 1] = prefix[i] + stones[i];
    int[][] dp = new int[n][n];
    for (int len = k; len <= n; len++) {
        for (int i = 0; i + len - 1 < n; i++) {
            int j = i + len - 1;
            dp[i][j] = Integer.MAX_VALUE;
            for (int m = i; m < j; m += k - 1)
                dp[i][j] = Math.min(dp[i][j], dp[i][m] + dp[m + 1][j]);
            if ((len - 1) % (k - 1) == 0)
                dp[i][j] += prefix[j + 1] - prefix[i];
        }
    }
    return dp[0][n - 1];
}

public int stoneGameVII(int[] stones) {
    int n = stones.length;
    int[] prefix = new int[n + 1];
    for (int i = 0; i < n; i++) prefix[i + 1] = prefix[i] + stones[i];
    int[][] dp = new int[n][n];
    for (int len = 2; len <= n; len++) {
        for (int i = 0; i + len - 1 < n; i++) {
            int j = i + len - 1;
            int removeLeft = (prefix[j + 1] - prefix[i + 1]) - dp[i + 1][j];
            int removeRight = (prefix[j] - prefix[i]) - dp[i][j - 1];
            dp[i][j] = Math.max(removeLeft, removeRight);
        }
    }
    return dp[0][n - 1];
}

public int stoneGameV(int[] stoneValue) {
    int n = stoneValue.length;
    int[] prefix = new int[n + 1];
    for (int i = 0; i < n; i++) prefix[i + 1] = prefix[i] + stoneValue[i];
    Integer[][] memo = new Integer[n][n];
    return solve(0, n - 1, prefix, memo);
}

private int solve(int i, int j, int[] prefix, Integer[][] memo) {
    if (i == j) return 0;
    if (memo[i][j] != null) return memo[i][j];
    int best = 0;
    for (int m = i; m < j; m++) {
        int left = prefix[m + 1] - prefix[i];
        int right = prefix[j + 1] - prefix[m + 1];
        if (left < right) best = Math.max(best, left + solve(i, m, prefix, memo));
        else if (left > right) best = Math.max(best, right + solve(m + 1, j, prefix, memo));
        else best = Math.max(best, left + Math.max(solve(i, m, prefix, memo), solve(m + 1, j, prefix, memo)));
    }
    return memo[i][j] = best;
}

public int removeBoxes(int[] boxes) {
    int n = boxes.length;
    int[][][] dp = new int[n][n][n];
    return calc(boxes, dp, 0, n - 1, 0);
}

private int calc(int[] boxes, int[][][] dp, int i, int j, int k) {
    if (i > j) return 0;
    if (dp[i][j][k] != 0) return dp[i][j][k];
    int i0 = i, k0 = k;
    while (i < j && boxes[i] == boxes[i + 1]) { i++; k++; }
    int res = (k + 1) * (k + 1) + calc(boxes, dp, i + 1, j, 0);
    for (int m = i + 1; m <= j; m++)
        if (boxes[m] == boxes[i])
            res = Math.max(res,
                    calc(boxes, dp, i + 1, m - 1, 0) + calc(boxes, dp, m, j, k + 1));
    dp[i0][j][k0] = res;
    return res;
}

public int strangePrinter(String s) {
    if (s == null || s.isEmpty()) return 0;
    int n = s.length();
    int[][] dp = new int[n][n];
    for (int i = n - 1; i >= 0; i--) {
        dp[i][i] = 1;
        for (int j = i + 1; j < n; j++) {
            dp[i][j] = dp[i][j - 1] + 1;
            for (int k = i; k < j; k++)
                if (s.charAt(k) == s.charAt(j))
                    dp[i][j] = Math.min(dp[i][j],
                            dp[i][k] + (k + 1 <= j - 1 ? dp[k + 1][j - 1] : 0));
        }
    }
    return dp[0][n - 1];
}

public int getMoneyAmount(int n) {
