}
private int maxProfit(int k, int[] prices) {
    int n = prices.length;
    if (n == 0 || k == 0) return 0;
    int[] buy = new int[k + 1], sell = new int[k + 1];
    Arrays.fill(buy, Integer.MIN_VALUE);
    for (int p : prices)
        for (int j = 1; j <= k; j++) {
            buy[j]  = Math.max(buy[j], sell[j - 1] - p);
            sell[j] = Math.max(sell[j], buy[j] + p);
        }
    return sell[k];
}

public int maxProfit(int k, int[] prices) {
    int n = prices.length;
    if (n == 0 || k == 0) return 0;
    if (k >= n / 2) {
        int profit = 0;
        for (int i = 1; i < n; i++)
            if (prices[i] > prices[i - 1]) profit += prices[i] - prices[i - 1];
        return profit;
    }
    int[] buy = new int[k + 1], sell = new int[k + 1];
    Arrays.fill(buy, Integer.MIN_VALUE);
    for (int p : prices)
        for (int j = 1; j <= k; j++) {
            buy[j]  = Math.max(buy[j], sell[j - 1] - p);
            sell[j] = Math.max(sell[j], buy[j] + p);
        }
    return sell[k];
}

public int maxProfit(int[] prices) {
    int hold = Integer.MIN_VALUE, sold = 0, rest = 0;
    for (int p : prices) {
        int prevSold = sold;
        sold = hold + p;
        hold = Math.max(hold, rest - p);
        rest = Math.max(rest, prevSold);
    }
    return Math.max(sold, rest);
}

public int maxProfit(int[] prices, int fee) {
    int cash = 0, hold = -prices[0];
    for (int i = 1; i < prices.length; i++) {
        cash = Math.max(cash, hold + prices[i] - fee);
        hold = Math.max(hold, cash - prices[i]);
    }
    return cash;
}

public boolean canPartitionKSubsets(int[] nums, int k) {
    int sum = 0;
    for (int x : nums) sum += x;
    if (sum % k != 0) return false;
    int target = sum / k, n = nums.length;
    Arrays.sort(nums);
    if (nums[n - 1] > target) return false;
    int[] dp = new int[1 << n];
    Arrays.fill(dp, -1);
    dp[0] = 0;
    for (int mask = 0; mask < (1 << n); mask++) {
        if (dp[mask] == -1) continue;
        for (int i = 0; i < n; i++) {
            if ((mask & (1 << i)) == 0 && dp[mask] + nums[i] <= target) {
                int next = mask | (1 << i);
                if (dp[next] == -1)
                    dp[next] = (dp[mask] + nums[i]) % target;
            }
        }
    }
    return dp[(1 << n) - 1] == 0;
}

public int shortestPathLength(int[][] graph) {
    int n = graph.length;
    if (n == 1) return 0;
    int full = (1 << n) - 1;
    boolean[][] visited = new boolean[n][1 << n];
    Deque<int[]> queue = new ArrayDeque<>();
    for (int i = 0; i < n; i++) {
        queue.offer(new int[]{i, 1 << i});
        visited[i][1 << i] = true;
    }
    int steps = 0;
    while (!queue.isEmpty()) {
        int size = queue.size();
        for (int s = 0; s < size; s++) {
            int[] cur = queue.poll();
            int node = cur[0], mask = cur[1];
            if (mask == full) return steps;
            for (int next : graph[node]) {
                int nmask = mask | (1 << next);
                if (!visited[next][nmask]) {
                    visited[next][nmask] = true;
                    queue.offer(new int[]{next, nmask});
                }
            }
        }
        steps++;
    }
    return -1;
}

public int connectTwoGroups(List<List<Integer>> cost) {
    int m = cost.size(), n = cost.get(0).size();
    int[] minConnect = new int[n];
    Arrays.fill(minConnect, Integer.MAX_VALUE);
    for (int i = 0; i < m; i++)
        for (int j = 0; j < n; j++)
            minConnect[j] = Math.min(minConnect[j], cost.get(i).get(j));
    Integer[][] memo = new Integer[m][1 << n];
    return dfs(0, 0, cost, minConnect, memo, m, n);
}
private int dfs(int i, int mask, List<List<Integer>> cost, int[] minConnect,
                Integer[][] memo, int m, int n) {
    if (i == m) {
        int total = 0;
        for (int j = 0; j < n; j++)
            if ((mask & (1 << j)) == 0) total += minConnect[j];
        return total;
    }
    if (memo[i][mask] != null) return memo[i][mask];
    int best = Integer.MAX_VALUE;
    for (int j = 0; j < n; j++) {
        int c = cost.get(i).get(j) + dfs(i + 1, mask | (1 << j), cost, minConnect, memo, m, n);
        best = Math.min(best, c);
    }
    return memo[i][mask] = best;
}

public String shortestSuperstring(String[] words) {
    int n = words.length;
    int[][] overlap = new int[n][n];
    for (int i = 0; i < n; i++)
        for (int j = 0; j < n; j++)
            if (i != j) overlap[i][j] = calcOverlap(words[i], words[j]);
    int[][] dp = new int[1 << n][n];
    int[][] parent = new int[1 << n][n];
    for (int[] row : parent) Arrays.fill(row, -1);
    for (int mask = 1; mask < (1 << n); mask++)
        for (int i = 0; i < n; i++) {
            if ((mask & (1 << i)) == 0) continue;
            int prevMask = mask ^ (1 << i);
            if (prevMask == 0) continue;
            for (int j = 0; j < n; j++) {
                if ((prevMask & (1 << j)) == 0) continue;
                int val = dp[prevMask][j] + overlap[j][i];
                if (val > dp[mask][i]) {
                    dp[mask][i] = val;
                    parent[mask][i] = j;
                }
            }
        }
    int full = (1 << n) - 1, last = 0, best = -1;
    for (int i = 0; i < n; i++)
        if (dp[full][i] > best) { best = dp[full][i]; last = i; }
    List<Integer> order = new ArrayList<>();
    int mask = full, cur = last;
    while (cur != -1) {
        order.add(cur);
        int p = parent[mask][cur];
        mask ^= (1 << cur);
        cur = p;
    }
    Collections.reverse(order);
    StringBuilder sb = new StringBuilder(words[order.get(0)]);
    for (int k = 1; k < order.size(); k++) {
        int ov = overlap[order.get(k - 1)][order.get(k)];
        sb.append(words[order.get(k)].substring(ov));
    }
    return sb.toString();
}
private int calcOverlap(String a, String b) {
    int max = Math.min(a.length(), b.length());
    for (int len = max; len > 0; len--)
        if (a.regionMatches(a.length() - len, b, 0, len)) return len;
    return 0;
}

public int maxStudents(char[][] seats) {
    int m = seats.length, n = seats[0].length;
    int[] valid = new int[m];
    for (int i = 0; i < m; i++)
        for (int j = 0; j < n; j++)
            if (seats[i][j] == '.') valid[i] |= (1 << j);
    int[] prev = new int[1 << n];
    Arrays.fill(prev, -1);
    prev[0] = 0;
    for (int i = 0; i < m; i++) {
        int[] cur = new int[1 << n];
        Arrays.fill(cur, -1);
        for (int mask = 0; mask < (1 << n); mask++) {
            if ((mask & valid[i]) != mask) continue;
            if ((mask & (mask << 1)) != 0) continue;
            for (int pmask = 0; pmask < (1 << n); pmask++) {
                if (prev[pmask] == -1) continue;
                if ((mask & (pmask << 1)) != 0) continue;
                if ((mask & (pmask >> 1)) != 0) continue;
                cur[mask] = Math.max(cur[mask], prev[pmask] + Integer.bitCount(mask));
            }
        }
        prev = cur;
    }
    int ans = 0;
    for (int v : prev) ans = Math.max(ans, v);
    return ans;
}

public int numberWays(List<List<Integer>> hats) {
    final int MOD = 1_000_000_007;
    int n = hats.size();
    List<List<Integer>> hatToPeople = new ArrayList<>();
    for (int h = 0; h <= 40; h++) hatToPeople.add(new ArrayList<>());
    for (int p = 0; p < n; p++)
        for (int h : hats.get(p))
            hatToPeople.get(h).add(p);
    int full = (1 << n) - 1;
    long[] dp = new long[1 << n];
    dp[0] = 1;
    for (int h = 1; h <= 40; h++) {
        long[] next = dp.clone();
        for (int mask = 0; mask <= full; mask++) {
            if (dp[mask] == 0) continue;
            for (int p : hatToPeople.get(h)) {
                if ((mask & (1 << p)) != 0) continue;
                int nmask = mask | (1 << p);
                next[nmask] = (next[nmask] + dp[mask]) % MOD;
            }
        }
        dp = next;
    }
    return (int) dp[full];
}

public int countNumbersWithUniqueDigits(int n) {
    if (n == 0) return 1;
    int count = 10;          // all single digits 0-9
    int unique = 9;          // running product for current length
    int available = 9;       // digits still free for next position
    for (int i = 2; i <= n; i++) {
        unique *= available; // extend from length i-1 to i
        count += unique;
        available--;
    }
    return count;
}

public int atMostNGivenDigitSet(String[] digits, int n) {
    String s = String.valueOf(n);
    int K = s.length();
    int D = digits.length;
    int[] pow = new int[K + 1];
    pow[0] = 1;
    for (int i = 1; i <= K; i++) pow[i] = pow[i - 1] * D;
    int ans = 0;
    // numbers with fewer digits than n
    for (int i = 1; i < K; i++) ans += pow[i];
    // numbers with exactly K digits, staying <= n
    for (int i = 0; i < K; i++) {
        char c = s.charAt(i);
        boolean matched = false;
        for (String d : digits) {
            char dc = d.charAt(0);
            if (dc < c) {
                ans += pow[K - i - 1];   // this position smaller -> rest free
            } else if (dc == c) {
                matched = true;          // can keep tight prefix
            }
        }
        if (!matched) return ans;        // cannot match n[i], no more equal prefixes
    }
    return ans + 1;                      // n itself is formable
}

class Solution {
    int MOD = 1_000_000_007;
    int minS, maxS;
    Integer[][] dp;

    public int count(String num1, String num2, int min_sum, int max_sum) {
        this.minS = min_sum;
        this.maxS = max_sum;
        int a = solve(num2);        // count in [0, num2]
        int b = solve(num1);        // count in [0, num1]
        int res = ((a - b) % MOD + MOD) % MOD;   // (num1, num2]
        int s = 0;
        for (int i = 0; i < num1.length(); i++) s += num1.charAt(i) - '0';
        if (s >= minS && s <= maxS) res = (res + 1) % MOD;   // add back num1
        return res;
    }

    int solve(String num) {
        dp = new Integer[num.length()][maxS + 1];
        return dfs(num, 0, 0, true);
    }

    int dfs(String num, int idx, int sum, boolean tight) {
        if (sum > maxS) return 0;
        if (idx == num.length()) return sum >= minS ? 1 : 0;
        if (!tight && dp[idx][sum] != null) return dp[idx][sum];
        int limit = tight ? num.charAt(idx) - '0' : 9;
        long res = 0;
        for (int d = 0; d <= limit; d++) {
            res += dfs(num, idx + 1, sum + d, tight && d == limit);
        }
        res %= MOD;
        if (!tight) dp[idx][sum] = (int) res;
        return (int) res;
    }
}

public int numDupDigitsAtMostN(int n) {
    return n - countUnique(n);
}

private int countUnique(int n) {
    String s = String.valueOf(n);
    int K = s.length();
    int res = 0;
    // numbers with fewer digits than n
    for (int i = 1; i < K; i++) res += 9 * perm(9, i - 1);
    // equal length, distinct, tight scan
    boolean[] used = new boolean[10];
    for (int i = 0; i < K; i++) {
        int cur = s.charAt(i) - '0';
        for (int d = (i == 0 ? 1 : 0); d < cur; d++) {
            if (!used[d]) res += perm(9 - i, K - i - 1);
        }
        if (used[cur]) return res;   // n has a repeat in its prefix, stop
        used[cur] = true;
        if (i == K - 1) res += 1;    // n itself is all-distinct
    }
    return res;
}

// permutations: m * (m-1) * ... * (m-k+1)
private int perm(int m, int k) {
    int r = 1;
    for (int i = 0; i < k; i++) r *= (m - i);
    return r;
}

public int countSpecialNumbers(int n) {
    String s = String.valueOf(n);
    int K = s.length();
    long res = 0;
    // fewer digits than n
    for (int i = 1; i < K; i++) res += 9L * perm(9, i - 1);
    // same length, tight
    boolean[] used = new boolean[10];
    for (int i = 0; i < K; i++) {
        int cur = s.charAt(i) - '0';
        for (int d = (i == 0 ? 1 : 0); d < cur; d++) {
            if (!used[d]) res += perm(9 - i, K - i - 1);
        }
        if (used[cur]) return (int) res;   // repeat in n's prefix
        used[cur] = true;
        if (i == K - 1) res += 1;          // n itself is special
    }
    return (int) res;
}

// m * (m-1) * ... * (m-k+1)
private long perm(int m, int k) {
    long r = 1;
    for (int i = 0; i < k; i++) r *= (m - i);
    return r;
}

public int findIntegers(int n) {
    int[] f = new int[32];
    f[0] = 1;
    f[1] = 2;
    for (int i = 2; i < 32; i++) f[i] = f[i - 1] + f[i - 2];
    int prevBit = 0, res = 0;
    for (int i = 30; i >= 0; i--) {
        if ((n & (1 << i)) != 0) {
            res += f[i];                 // put 0 here, rest of bits free & valid
            if (prevBit == 1) return res; // n has adjacent ones -> stop, n invalid
            prevBit = 1;
        } else {
            prevBit = 0;
        }
    }
    return res + 1;                       // include n itself
}

class Solution {
    public int rob(TreeNode root) {
        int[] r = dfs(root);
        return Math.max(r[0], r[1]);
    }

    // r[0] = best if this node NOT robbed, r[1] = best if robbed
    private int[] dfs(TreeNode node) {
        if (node == null) return new int[]{0, 0};
        int[] l = dfs(node.left);
        int[] r = dfs(node.right);
        int skip = Math.max(l[0], l[1]) + Math.max(r[0], r[1]);
        int rob = node.val + l[0] + r[0];
        return new int[]{skip, rob};
    }
}

