class Solution {
    private List<Integer>[] graph;
    private int[] count;
    private int[] ans;
    private int n;

    @SuppressWarnings("unchecked")
    public int[] sumOfDistancesInTree(int n, int[][] edges) {
        this.n = n;
        graph = new List[n];
        for (int i = 0; i < n; i++) graph[i] = new ArrayList<>();
        for (int[] e : edges) {
            graph[e[0]].add(e[1]);
            graph[e[1]].add(e[0]);
        }
        count = new int[n];
        ans = new int[n];
        dfs1(0, -1);
        dfs2(0, -1);
        return ans;
    }

    private void dfs1(int node, int parent) {
        count[node] = 1;
        for (int child : graph[node]) {
            if (child == parent) continue;
            dfs1(child, node);
            count[node] += count[child];
            ans[node] += ans[child] + count[child];
        }
    }

    private void dfs2(int node, int parent) {
        for (int child : graph[node]) {
            if (child == parent) continue;
            ans[child] = ans[node] - count[child] + (n - count[child]);
            dfs2(child, node);
        }
    }
}

class Solution {
    private List<Integer>[] graph;
    private int diameter = 0;

    @SuppressWarnings("unchecked")
    public int treeDiameter(int[][] edges) {
        int n = edges.length + 1;
        graph = new List[n];
        for (int i = 0; i < n; i++) graph[i] = new ArrayList<>();
        for (int[] e : edges) {
            graph[e[0]].add(e[1]);
            graph[e[1]].add(e[0]);
        }
        dfs(0, -1);
        return diameter;
    }

    // returns longest downward chain (edge count) from node
    private int dfs(int node, int parent) {
        int max1 = 0, max2 = 0;
        for (int nei : graph[node]) {
            if (nei == parent) continue;
            int d = dfs(nei, node) + 1;
            if (d > max1) { max2 = max1; max1 = d; }
            else if (d > max2) { max2 = d; }
        }
        diameter = Math.max(diameter, max1 + max2);
        return max1;
    }
}

class Solution {
    private int maxSum = 0;

    public int maxSumBST(TreeNode root) {
        dfs(root);
        return maxSum;
    }

    // returns {isBST(1/0), min, max, sum}
    private int[] dfs(TreeNode node) {
        if (node == null) return new int[]{1, Integer.MAX_VALUE, Integer.MIN_VALUE, 0};
        int[] l = dfs(node.left);
        int[] r = dfs(node.right);
        if (l[0] == 1 && r[0] == 1 && node.val > l[2] && node.val < r[1]) {
            int sum = l[3] + r[3] + node.val;
            maxSum = Math.max(maxSum, sum);
            return new int[]{1, Math.min(l[1], node.val), Math.max(r[2], node.val), sum};
        }
        return new int[]{0, 0, 0, 0};   // not a BST
    }
}

